<?php

declare(strict_types=1);

namespace Nowo\UiKitBundle\Tests\Unit;

use PHPUnit\Framework\TestCase;

/**
 * nowo-ui.css is nowo-ui.unlayered.css inside `@layer nowo-ui` (REQ-UI-003 cascade): generated by
 * `pnpm run build:css` (.scripts/build-layered-css.mjs), never edited by hand.
 */
final class LayeredCssTest extends TestCase
{
    private const DIR = __DIR__.'/../../src/Resources/public/css';

    public function testLayeredStylesheetIsTheUnlayeredSourceInsideTheNowoUiLayer(): void
    {
        $source = (string) file_get_contents(self::DIR.'/nowo-ui.unlayered.css');
        $header = (string) file_get_contents(__DIR__.'/../../.scripts/nowo-ui-layer-header.css');
        $expected = $header.'@layer nowo-ui {'."\n".(str_ends_with($source, "\n") ? $source : $source."\n").'}'."\n";

        self::assertSame($expected, (string) file_get_contents(self::DIR.'/nowo-ui.css'), 'nowo-ui.css is stale: run `pnpm run build:css` (make assets).');
    }

    public function testLayerOrderKeepsTheKitAboveBaseAndBelowUtilities(): void
    {
        $css = (string) file_get_contents(self::DIR.'/nowo-ui.css');

        self::assertMatchesRegularExpression('/^@layer theme, base, nowo-ui, components, utilities;$/m', $css);
        self::assertSame(1, preg_match_all('/^@layer nowo-ui \{$/m', $css));
        // nothing outside the layer but the header comment and the order statement
        $outside = (string) preg_replace('/@layer nowo-ui \{.*\}\s*$/s', '', $css);
        $outside = (string) preg_replace('#/\*.*?\*/#s', '', $outside);
        self::assertSame('@layer theme, base, nowo-ui, components, utilities;', trim($outside));
    }

    public function testUnlayeredSourceHasNoLayerAndKeepsTheRootTokenFallbacks(): void
    {
        $source = (string) file_get_contents(self::DIR.'/nowo-ui.unlayered.css');

        self::assertStringNotContainsString('@layer', $source);
        self::assertStringContainsString(':root:where(:not([data-nowo-ui-host-tokens]))', $source);
        self::assertStringContainsString('--nowo-ui-primary: #2563eb;', $source);
    }
}
